// Двойные и одинарные кавычки — почти взаимозаменяемы:
const a = "обычная строка";
const b = 'тоже строка';

// Обратные кавычки — шаблонный литерал:
const name = "Amber";
const age = 25;
const message = `Привет, ${name}! Тебе ${age} лет.`;
console.log(message);  // Привет, Amber! Тебе 25 лет.

// ${...} вычисляет ЛЮБОЕ выражение, не только переменную:
console.log(`Сумма: ${2 + 2}`);  // Сумма: 4

const name = "Amber";
const age = 25;

// Старый способ — конкатенация (легко ошибиться с пробелами):
const old = "Привет, " + name + "! Тебе " + age + " лет.";

// Новый способ — шаблонный литерал (читается как готовый текст):
const modern = `Привет, ${name}! Тебе ${age} лет.`;

// Оба дадут одинаковый результат, но второй понятнее:
console.log(modern);  // Привет, Amber! Тебе 25 лет.

const name = "amber";
console.log(name.toUpperCase());   // AMBER
console.log("HELLO".toLowerCase()); // hello

// Нормализация ввода для проверки:
const input = "AmBeR";
if (input.toLowerCase() === "amber") {
  console.log("Имя совпало");  // сработает для любого регистра
}

const word = "JavaScript";
console.log(word.slice(0, 4));   // Java — символы 0,1,2,3 (4 не включается)
console.log(word.slice(4));      // Script — с индекса 4 и до конца
console.log(word.slice(-6));     // Script — последние 6 символов
console.log(word.slice(0, -4));  // Java — от начала до -4 (без последних 4)

// Важно: end НЕ включается. slice(0,4) берёт 4 символа, а не 5.

const csv = "apple,banana,cherry";
const fruits = csv.split(",");
console.log(fruits);         // ["apple", "banana", "cherry"]
console.log(fruits.length);  // 3
console.log(fruits[1]);      // banana — доступ к элементу массива

// Разбиение по пробелу:
console.log("раз два три".split(" "));  // ["раз", "два", "три"]

const text = "яблоко банан яблоко";
console.log(text.replace("яблоко", "апельсин"));
// "апельсин банан яблоко" — только ПЕРВОЕ вхождение!

// Заменить ВСЕ — нужно регулярное выражение с флагом g:
console.log(text.replace(/яблоко/g, "апельсин"));
// "апельсин банан апельсин" — теперь все

const original = "amber";
const upper = original.toUpperCase();  // вернула НОВУЮ строку
console.log(original);  // "amber" — оригинал не изменился!
console.log(upper);     // "AMBER"

// Если хочешь 'изменить' — перезапиши переменную (нужен let!):
let city = "moscow";
city = city.toUpperCase();  // теперь city === "MOSCOW"

const email = "user@example.com";
console.log(email.includes("@"));     // true

const text = "Hello, World";
console.log(text.includes("World"));  // true
console.log(text.includes("world"));  // false — регистр важен!

// Нормализация для регистронезависимой проверки:
console.log(text.toLowerCase().includes("world"));  // true
